 10 | import type {Dispatcher} from 'react-reconciler/src/ReactInternalTypes';
 11 | import type {
 12 |   ReactContext,
 13 |   StartTransitionOptions,
 14 |   Usable,
 15 |   Awaited,
 16 | } from 'shared/ReactTypes';
 17 | import {REACT_CONSUMER_TYPE} from 'shared/ReactSymbols';
 18 | 
 19 | import ReactSharedInternals from 'shared/ReactSharedInternals';
 20 | 
 21 | import {enableAsyncActions} from 'shared/ReactFeatureFlags';
 22 | import {
 23 |   enableContextProfiling,
 24 |   enableLazyContextPropagation,
 25 | } from '../../shared/ReactFeatureFlags';
 26 | 
 27 | type BasicStateAction<S> = (S => S) | S;
 28 | type Dispatch<A> = A => void;
 29 | 
 30 | function resolveDispatcher() {
 31 |   const dispatcher = ReactSharedInternals.H;
 32 |   if (__DEV__) {
 33 |     if (dispatcher === null) {
 34 |       console.error(
 35 |         'Invalid hook call. Hooks can only be called inside of the body of a function component. This could happen for' +
 36 |           ' one of the following reasons:\n' +
 37 |           '1. You might have mismatching versions of React and the renderer (such as React DOM)\n' +
 38 |           '2. You might be breaking the Rules of Hooks\n' +
 39 |           '3. You might have more than one copy of React in the same app\n' +
 40 |           'See https://react.dev/link/invalid-hook-call for tips about how to debug and fix this problem.',
 41 |       );
 42 |     }
 43 |   }
 44 |   // Will result in a null access error if accessed outside render phase. We
 45 |   // intentionally don't throw our own error because this is in a hot path.
 46 |   // Also helps ensure this is inlined.
 47 |   return ((dispatcher: any): Dispatcher);
 48 | }
 49 | 
 50 | export function getCacheForType<T>(resourceType: () => T): T {
 51 |   const dispatcher = ReactSharedInternals.A;
 52 |   if (!dispatcher) {
 53 |     // If there is no dispatcher, then we treat this as not being cached.
 54 |     return resourceType();
 55 |   }
 56 |   return dispatcher.getCacheForType(resourceType);
 57 | }
 58 | 
 59 | export function useContext<T>(Context: ReactContext<T>): T {
 60 |   const dispatcher = resolveDispatcher();
 61 |   if (__DEV__) {
 62 |     if (Context.$$typeof === REACT_CONSUMER_TYPE) {
 63 |       console.error(
 64 |         'Calling useContext(Context.Consumer) is not supported and will cause bugs. ' +
 65 |           'Did you mean to call useContext(Context) instead?',
 66 |       );
 67 |     }
 68 |   }
 69 |   return dispatcher.useContext(Context);
 70 | }
 71 | 
 72 | export function unstable_useContextWithBailout<T>(
 73 |   context: ReactContext<T>,
 74 |   select: (T => Array<mixed>) | null,
 75 | ): T {
 76 |   if (!(enableLazyContextPropagation && enableContextProfiling)) {
 77 |     throw new Error('Not implemented.');
 78 |   }
 79 | 
 80 |   const dispatcher = resolveDispatcher();
 81 |   if (__DEV__) {
 82 |     if (context.$$typeof === REACT_CONSUMER_TYPE) {
 83 |       console.error(
 84 |         'Calling useContext(Context.Consumer) is not supported and will cause bugs. ' +
 85 |           'Did you mean to call useContext(Context) instead?',
 86 |       );
 87 |     }
 88 |   }
 89 |   // $FlowFixMe[not-a-function] This is unstable, thus optional
 90 |   return dispatcher.unstable_useContextWithBailout(context, select);
 91 | }
 92 | 
 93 | export function useState<S>(
 94 |   initialState: (() => S) | S,
 95 | ): [S, Dispatch<BasicStateAction<S>>] {
 96 |   const dispatcher = resolveDispatcher();
 97 |   return dispatcher.useState(initialState);
 98 | }
 99 | 
100 | export function useReducer<S, I, A>(
101 |   reducer: (S, A) => S,
102 |   initialArg: I,
103 |   init?: I => S,
104 | ): [S, Dispatch<A>] {
105 |   const dispatcher = resolveDispatcher();
106 |   return dispatcher.useReducer(reducer, initialArg, init);
107 | }
108 | 
109 | export function useRef<T>(initialValue: T): {current: T} {
110 |   const dispatcher = resolveDispatcher();
111 |   return dispatcher.useRef(initialValue);
112 | }
