114 | export function useEffect(
115 |   create: () => (() => void) | void,
116 |   deps: Array<mixed> | void | null,
117 | ): void {
118 |   const dispatcher = resolveDispatcher();
119 |   return dispatcher.useEffect(create, deps);
120 | }
