163 | export function useDebugValue<T>(
164 |   value: T,
165 |   formatterFn: ?(value: T) => mixed,
166 | ): void {
167 |   if (__DEV__) {
168 |     const dispatcher = resolveDispatcher();
169 |     return dispatcher.useDebugValue(value, formatterFn);
170 |   }
171 | }
