229 | export function useOptimistic<S, A>(
230 |   passthrough: S,
231 |   reducer: ?(S, A) => S,
232 | ): [S, (A) => void] {
233 |   const dispatcher = resolveDispatcher();
234 |   // $FlowFixMe[not-a-function] This is unstable, thus optional
235 |   return dispatcher.useOptimistic(passthrough, reducer);
236 | }
237 | 
238 | export function useActionState<S, P>(
239 |   action: (Awaited<S>, P) => S,
240 |   initialState: Awaited<S>,
241 |   permalink?: string,
242 | ): [Awaited<S>, (P) => void, boolean] {
243 |   if (!enableAsyncActions) {
244 |     throw new Error('Not implemented.');
245 |   } else {
246 |     const dispatcher = resolveDispatcher();
247 |     // $FlowFixMe[not-a-function] This is unstable, thus optional
248 |     return dispatcher.useActionState(action, initialState, permalink);
249 |   }
250 | }
